import consts, { DatepickerView } from './common/consts';
import {
    addEventListener,
    classNames,
    closest,
    createElement,
    getDaysCount,
    getDecade,
    getEl,
    getParsedDate,
    isDateBigger,
    isDateSmaller,
    isSameDate,
    subDays,
} from './common/utils';
import DatepickerCell from './DatepickerCell';
import  { DatepickerOptions } from './Default';
import './DatepickerBody.scss';

// Type for the static date generator functions
type DateGenerator = (dp: any, cb?: (date: Date) => void) => Date[];

const templates: Record<string, string> = {
    [consts.days]: '' +
        '<div class="datepicker-body--day-names"></div>' +
        `<div class="datepicker-body--cells -${consts.days}-"></div>`,
    [consts.months]: `<div class="datepicker-body--cells -${consts.months}-"></div>`,
    [consts.years]: `<div class="datepicker-body--cells -${consts.years}-"></div>`
};

const cellClassName = '.datepicker-cell';

interface DatepickerBodyArgs {
    dp: any; // Replace with Datepicker type when ready
    type: any;
    opts: DatepickerOptions;
}

export default class DatepickerBody {
    dp: any;
    type: DatepickerView;
    opts: DatepickerOptions;
    cells: DatepickerCell[] = [];
    $el!: HTMLElement;
    $names: HTMLElement | null = null;
    $cells!: HTMLElement;
    pressed = false;
    isVisible = true;
    rangeFromFocused = false;
    rangeToFocused = false;

    constructor({ dp, type, opts }: DatepickerBodyArgs) {
        this.dp = dp;
        this.type = type;
        this.opts = opts;

        this.init();
    }

    init(): void {
        this._buildBaseHtml();
        if (this.type === consts.days) {
            this.renderDayNames();
        }
        this.render();
        this._bindEvents();
        this._bindDatepickerEvents();
    }

    _bindEvents(): void {
        const { range, dynamicRange } = this.opts;

                // addEventListener(this.$ranges, 'mouseleave', this.onMouseEnterLeave as EventListener);

        addEventListener(this.$el, 'mouseover', this.onMouseOverCell as EventListener);
        addEventListener(this.$el, 'mouseout', this.onMouseOutCell);
        addEventListener(this.$el, 'click', this.onClickBody  as EventListener);

        if (range && dynamicRange) {
            addEventListener(this.$el, 'mousedown', this.onMouseDown  as EventListener);
            addEventListener(this.$el, 'mousemove', this.onMouseMove  as EventListener);
            addEventListener(window.document as any, 'mouseup', this.onMouseUp);
        }
    }

    _bindDatepickerEvents(): void {
        this.dp.on(consts.eventChangeViewDate, this.onChangeViewDate);
        this.dp.on(consts.eventChangeCurrentView, this.onChangeCurrentView);
    }

    _buildBaseHtml(): void {
        this.$el = createElement({
            className: `datepicker-body -${this.type}-`,
            innerHtml: templates[this.type]
        });

        this.$names = getEl('.datepicker-body--day-names', this.$el);
        this.$cells = getEl('.datepicker-body--cells', this.$el) as HTMLElement;
    }

    _getDayNamesHtml(firstDay: number = this.dp.locale.firstDay): string {
        let html = '';
        const isWeekend = this.dp.isWeekend;
        const { onClickDayName } = this.opts;
        let curDay = firstDay;
        const totalDays = 7;
        let i = 0;

        while (i < totalDays) {
            const day = curDay % totalDays;
            const className = classNames('datepicker-body--day-name', {
                [consts.cssClassWeekend]: isWeekend(day),
                '-clickable-': !!onClickDayName
            });
            const dayName = this.dp.locale.daysMin[day];

            html += `<div class="${className}" data-day-index='${day}'>${dayName}</div>`;

            i++;
            curDay++;
        }
        return html;
    }

    renderDayNames(): void {
        if (this.$names) {
            this.$names.innerHTML = this._getDayNamesHtml();
        }
    }

    _generateCell(date: Date): DatepickerCell {
        const { type, dp, opts } = this;
        return new DatepickerCell({
            type,
            dp,
            opts,
            date,
            body: this
        });
    }

    _generateCells(): void {
        const getDates = DatepickerBody.getDatesFunction(this.type);

        getDates(this.dp, (date: Date) => {
            this.cells.push(this._generateCell(date));
        });
    }

    show(): void {
        this.isVisible = true;
        this.$el.classList.remove('-hidden-');
    }

    hide(): void {
        this.isVisible = false;
        this.$el.classList.add('-hidden-');
    }

    destroyCells(): void {
        this.cells.forEach(c => c.destroy());
        this.cells = [];
        this.$cells.innerHTML = '';
    }

    destroy(): void {
        this.destroyCells();
        this.dp.off(consts.eventChangeViewDate, this.onChangeViewDate);
        this.dp.off(consts.eventChangeCurrentView, this.onChangeCurrentView);
    }

    handleClick = (e: MouseEvent): void => {
        const target = e.target as HTMLElement;
        const $cell = target.closest(cellClassName) as any;
        if (!$cell) return;

        const cell: DatepickerCell = $cell.adpCell;
        if (cell.isDisabled) return;

        if (!this.dp.isMinViewReached) {
            this.dp.down();
            return;
        }

        const alreadySelectedDate = this.dp._checkIfDateIsSelected(cell.date, cell.type);

        if (alreadySelectedDate) {
            this.dp._handleAlreadySelectedDates(alreadySelectedDate, cell.date);
        } else {
            this.dp.selectDate(cell.date);
        }
    }

    handleDayNameClick = (e: MouseEvent): void => {
        const target = e.target as HTMLElement;
        const index = target.getAttribute('data-day-index');

        if (this.opts.onClickDayName && index !== null) {
            this.opts.onClickDayName({
                dayIndex: Number(index),
                datepicker: this.dp
            });
        }
    }

    onChangeCurrentView = (view: DatepickerView): void => {
        if (view !== this.type) {
            this.hide();
        } else {
            this.show();
            this.render();
        }
    }

    onMouseOverCell = (e: MouseEvent): void => {
        const $cell = closest(e.target as HTMLElement, cellClassName) as any;
        this.dp.setFocusDate($cell ? $cell.adpCell.date : false);
    }

    onMouseOutCell = (): void => {
        this.dp.setFocusDate(false);
    }

    onClickBody = (e: MouseEvent): void => {
        const { onClickDayName } = this.opts;
        const target = e.target as HTMLElement;

        if (target.closest(cellClassName)) {
            this.handleClick(e);
        }

        if (onClickDayName && target.closest('.datepicker-body--day-name')) {
            this.handleDayNameClick(e);
        }
    }

    onMouseDown = (e: MouseEvent): void => {
        this.pressed = true;

        const $cell = closest(e.target as HTMLElement, cellClassName) as any;
        const cell = $cell && $cell.adpCell;

        if (cell && isSameDate(cell.date, this.dp.rangeDateFrom)) {
            this.rangeFromFocused = true;
        }
        if (cell && isSameDate(cell.date, this.dp.rangeDateTo)) {
            this.rangeToFocused = true;
        }
    }

    onMouseMove = (e: MouseEvent): void => {
        if (!this.pressed || !this.dp.isMinViewReached) return;
        e.preventDefault();

        const $cell = closest(e.target as HTMLElement, cellClassName) as any;
        const cell = $cell && $cell.adpCell;
        const { selectedDates, rangeDateTo, rangeDateFrom } = this.dp;

        if (!cell || cell.isDisabled) return;

        const { date } = cell;

        if (selectedDates.length === 2) {
            if (this.rangeFromFocused && !isDateBigger(date, rangeDateTo)) {
                const { hours, minutes } = getParsedDate(rangeDateFrom);
                date.setHours(hours);
                date.setMinutes(minutes);

                this.dp.rangeDateFrom = date;
                this.dp.replaceDate(rangeDateFrom, date);
            }
            if (this.rangeToFocused && !isDateSmaller(date, rangeDateFrom)) {
                const { hours, minutes } = getParsedDate(rangeDateTo);
                date.setHours(hours);
                date.setMinutes(minutes);

                this.dp.rangeDateTo = date;
                this.dp.replaceDate(rangeDateTo, date);
            }
        }
    }

    onMouseUp = (): void => {
        this.pressed = false;
        this.rangeFromFocused = false;
        this.rangeToFocused = false;
    }

    onChangeViewDate = (date: Date, oldViewDate: Date): void => {
        if (!this.isVisible) return;

        const decade1 = getDecade(date);
        const decade2 = getDecade(oldViewDate);

        switch (this.dp.currentView) {
            case (consts.days):
                if (isSameDate(date, oldViewDate, consts.months)) return;
                break;
            case (consts.months):
                if (isSameDate(date, oldViewDate, consts.years)) return;
                break;
            case (consts.years):
                if (decade1[0] === decade2[0] && decade1[1] === decade2[1]) return;
                break;
        }

        this.render();
    }

    render = (): void => {
        this.destroyCells();
        this._generateCells();
        this.cells.forEach((c) => {
            this.$cells.appendChild(c.render());
        });
    }

    static getDaysDates(dp: any, cb?: (date: Date) => void): Date[] {
        const { viewDate, opts: { fixedHeight }, locale: { firstDay } } = dp;
        const totalMonthDays = getDaysCount(viewDate);
        const { year, month } = getParsedDate(viewDate);
        const firstMonthDay = new Date(year, month, 1);
        const lastMonthDay = new Date(year, month, totalMonthDays);
        let daysFromPrevMonth = firstMonthDay.getDay() - firstDay;
        let daysFromNextMonth = 6 - lastMonthDay.getDay() + firstDay;

        daysFromPrevMonth = daysFromPrevMonth < 0 ? daysFromPrevMonth + 7 : daysFromPrevMonth;
        daysFromNextMonth = daysFromNextMonth > 6 ? daysFromNextMonth - 7 : daysFromNextMonth;

        const firstRenderDate = subDays(firstMonthDay, daysFromPrevMonth);
        let totalRenderDays = totalMonthDays + daysFromPrevMonth + daysFromNextMonth;
        const firstRenderDayDate = firstRenderDate.getDate();
        const { year: renderYear, month: renderMonth } = getParsedDate(firstRenderDate);
        let i = 0;

        if (fixedHeight) {
            totalRenderDays = 6 * 7;
        }

        const dates: Date[] = [];

        while (i < totalRenderDays) {
            const date = new Date(renderYear, renderMonth, firstRenderDayDate + i);
            if (cb) cb(date);
            dates.push(date);
            i++;
        }

        return dates;
    }

    static getMonthsDates(dp: any, cb?: (date: Date) => void): Date[] {
        const totalMonths = 12;
        const { year } = dp.parsedViewDate;
        let currentMonth = 0;
        const dates: Date[] = [];

        while (currentMonth < totalMonths) {
            const date = new Date(year, currentMonth);
            dates.push(date);
            if (cb) cb(date);
            currentMonth++;
        }

        return dates;
    }

    static getYearsDates(dp: any, cb?: (date: Date) => void): Date[] {
        const decade = getDecade(dp.viewDate);
        const firstYear = decade[0] - 1;
        const lastYear = decade[1] + 1;
        let year = firstYear;
        const dates: Date[] = [];

        while (year <= lastYear) {
            const date = new Date(year, 0);
            dates.push(date);
            if (cb) cb(date);
            year++;
        }

        return dates;
    }

    static getDatesFunction(viewType: DatepickerView = consts.days): DateGenerator {
        const map: Record<string, DateGenerator> = {
            [consts.days]: DatepickerBody.getDaysDates,
            [consts.months]: DatepickerBody.getMonthsDates,
            [consts.years]: DatepickerBody.getYearsDates,
        };
        return map[viewType];
    }
}